package com.rulecraft.decisionops.workflow;
import static org.assertj.core.api.Assertions.*;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.*;import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.DecisionExpressionService.ExpressionCommand;import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;import com.rulecraft.decisionops.identity.domain.*;import com.rulecraft.decisionops.identity.persistence.UserAccountRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectService;import com.rulecraft.decisionops.projects.domain.ProjectRole;import com.rulecraft.decisionops.versions.DecisionVersionService;import com.rulecraft.decisionops.versions.DecisionVersionService.CaptureCommand;import com.rulecraft.decisionops.workflow.ApprovalWorkflowService.*;import com.rulecraft.decisionops.workflow.domain.ChangeRequestState;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.crypto.password.PasswordEncoder;

@SpringBootTest class ApprovalWorkflowIntegrationTest {@Autowired ApprovalWorkflowService workflow;@Autowired DecisionVersionService versions;@Autowired DecisionExpressionService expressions;@Autowired DecisionGraphService graphs;@Autowired CatalogService catalog;@Autowired ProjectService projects;@Autowired UserAccountRepository users;@Autowired PasswordEncoder passwords;@Autowired Clock clock;RuleCraftPrincipal admin;@BeforeEach void actor(){admin=new RuleCraftPrincipal(users.findForLogin("acme-rules","admin@example.test").orElseThrow(),"acme-rules");}
@Test void submitsApprovesAndIdempotentlyPromotesLatestValidVersion(){var fixture=fixture();var captured=capture(fixture,"Baseline");var createId=UUID.randomUUID();var request=workflow.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCommand(createId,captured.id(),"Approve eligibility baseline","Ready for governed review"));assertThat(workflow.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCommand(createId,captured.id(),"Approve eligibility baseline","Ready for governed review")).id()).isEqualTo(request.id());var submitId=UUID.randomUUID();var submitted=workflow.submit(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(submitId,request.version(),"Validation complete"));assertThat(workflow.submit(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(submitId,request.version(),"Validation complete")).state()).isEqualTo(ChangeRequestState.SUBMITTED);var approved=workflow.approve(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),submitted.version(),"Reviewed against scenarios"));var promoteId=UUID.randomUUID();var promoted=workflow.promote(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(promoteId,approved.version(),"Set governed baseline"));assertThat(promoted.state()).isEqualTo(ChangeRequestState.PROMOTED);assertThat(workflow.promote(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(promoteId,approved.version(),"Set governed baseline")).state()).isEqualTo(ChangeRequestState.PROMOTED);var state=workflow.workflow(admin,fixture.projectId(),fixture.serviceId());assertThat(state.promotion().decisionVersionId()).isEqualTo(captured.id());assertThat(workflow.detail(admin,fixture.projectId(),fixture.serviceId(),request.id()).events()).extracting("eventType").containsExactly("CREATED","SUBMITTED","APPROVED","PROMOTED");}
@Test void enforcesReviewerAndOwnerSeparationAndNonDisclosure(){var fixture=fixture();var captured=capture(fixture,"Candidate");var editor=member(fixture.projectId(),"editor",ProjectRole.EDITOR);var reviewer=member(fixture.projectId(),"reviewer",ProjectRole.REVIEWER);var viewer=member(fixture.projectId(),"viewer",ProjectRole.VIEWER);var request=workflow.create(editor,fixture.projectId(),fixture.serviceId(),new CreateCommand(UUID.randomUUID(),captured.id(),"Editor request",null));var submitted=workflow.submit(editor,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),request.version(),null));assertCode("RC-PROJECT-REVIEW-FORBIDDEN",()->workflow.approve(editor,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),submitted.version(),null)));var approved=workflow.approve(reviewer,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),submitted.version(),"Independent review"));assertCode("RC-PROJECT-PROMOTE-FORBIDDEN",()->workflow.promote(reviewer,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),approved.version(),null)));assertThat(workflow.workflow(viewer,fixture.projectId(),fixture.serviceId()).requests()).hasSize(1);assertCode("RC-PROJECT-EDIT-FORBIDDEN",()->workflow.create(viewer,fixture.projectId(),fixture.serviceId(),new CreateCommand(UUID.randomUUID(),captured.id(),"Forbidden",null)));var outsiderAccount=users.save(new UserAccount(admin.tenantId(),"workflow-outsider"+UUID.randomUUID()+"@example.test","Workflow Outsider",passwords.encode("CorrectHorseBattery83!"),TenantRole.MEMBER,Instant.now(clock)));var outsider=new RuleCraftPrincipal(outsiderAccount,"acme-rules");assertCode("RC-PROJECT-NOT-FOUND",()->workflow.workflow(outsider,fixture.projectId(),fixture.serviceId()));}
@Test void rejectsInvalidAndStaleCandidatesAndIllegalTransitions(){var fixture=fixture();var first=capture(fixture,"First");var request=workflow.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCommand(UUID.randomUUID(),first.id(),"Review first",null));var submitted=workflow.submit(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),request.version(),null));var expression=expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()).orElseThrow();expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(expression.version(),"score >= 650"));capture(fixture,"Second");assertCode("RC-WORKFLOW-VERSION-STALE",()->workflow.approve(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),submitted.version(),null)));assertCode("RC-WORKFLOW-NOTE-REQUIRED",()->workflow.reject(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),submitted.version(),null)));var current=expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()).orElseThrow();expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(current.version(),"score >="));var invalid=capture(fixture,"Invalid");assertCode("RC-WORKFLOW-VERSION-INVALID",()->workflow.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCommand(UUID.randomUUID(),invalid.id(),"Invalid candidate",null)));assertCode("RC-WORKFLOW-STALE",()->workflow.submit(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),99L,null)));}
private RuleCraftPrincipal member(UUID projectId,String prefix,ProjectRole role){var now=Instant.now(clock);var account=users.save(new UserAccount(admin.tenantId(),prefix+UUID.randomUUID()+"@example.test",prefix+" workflow user",passwords.encode("CorrectHorseBattery82!"),TenantRole.MEMBER,now));projects.upsertMember(admin,projectId,account.getId(),role);return new RuleCraftPrincipal(account,"acme-rules");}private DecisionVersionService.VersionSummary capture(Fixture fixture,String label){var state=versions.working(admin,fixture.projectId(),fixture.serviceId());return versions.capture(admin,fixture.projectId(),fixture.serviceId(),new CaptureCommand(UUID.randomUUID(),label,"Workflow evidence",state.serviceVersion(),state.graphVersion(),state.fingerprint()));}private Fixture fixture(){var project=projects.create(admin,key("W"),"Approval workflow",null);var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("SVC"),"Eligibility workflow",null,List.of(new FieldCommand("score","Score",builtin(BuiltinType.NUMBER),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var input=port(GraphPortDirection.INPUT,"score",BuiltinType.NUMBER);var output=port(GraphPortDirection.OUTPUT,"approved",BuiltinType.BOOLEAN);var serviceInput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.INPUT).findFirst().orElseThrow().ports().getFirst();var serviceOutput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.OUTPUT).findFirst().orElseThrow().ports().getFirst();var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"threshold","Approval threshold",GraphNodeKind.DECISION,null,300,100,List.of(input,output)));graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of(edge(serviceInput.id(),input.id()),edge(output.id(),serviceOutput.id()))));var expression=expressions.initialize(admin,project.id(),service.id(),nodeId);expressions.update(admin,project.id(),service.id(),nodeId,new ExpressionCommand(expression.version(),"score >= 700"));return new Fixture(project.id(),service.id(),nodeId);}private CatalogService.TypeRefCommand builtin(BuiltinType type){return new CatalogService.TypeRefCommand(type,null);}private PortCommand port(GraphPortDirection direction,String key,BuiltinType type){return new PortCommand(UUID.randomUUID(),direction,key,key,new DecisionGraphService.TypeRefCommand(type,null),true,0);}private NodeCommand command(GraphNodeView node){return new NodeCommand(node.id(),node.nodeKey(),node.name(),node.kind(),node.serviceFieldKey(),node.positionX(),node.positionY(),node.ports().stream().map(port->new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),port.type(),port.required(),port.position())).toList());}private EdgeCommand edge(UUID source,UUID target){return new EdgeCommand(UUID.randomUUID(),source,target);}private String key(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase();}private void assertCode(String code,Runnable action){assertThatThrownBy(action::run).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo(code);}private record Fixture(UUID projectId,UUID serviceId,UUID nodeId){}
}
